import React, { useCallback, useMemo, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import {
  Button,
  Input,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  LinPageLayout,
  useCatalogTableBusy,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { analyticsService } from '../../../services/analytics/analyticsService';
import type { PeriodicAllocationJournalListingRow } from '../../../services/analytics/models';
import { formatDate, formatVnd } from '../../../utils/formatters';
import { exportExcel, monthStartEnd } from '../../../utils/exportExcel';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import erp from '../../../styles/erpPage.module.css';
import reportStyles from '../../../styles/erpReportPage.module.css';
import styles from './BangKeButToanPhanBoDinhKyPage.module.css';

const TEST_ID = 'rpt-bang-ke-but-toan-phan-bo-dinh-ky';
const PAGE_ID = 'baocao-bang-ke-but-toan-phan-bo-dinh-ky';
const TITLE = 'Bảng kê bút toán phân bổ định kỳ';

type RowTag = 'Detail' | 'Total';

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function readDrillDefaults(search: URLSearchParams, fallback: { fromDate: string; toDate: string }) {
  const fromDate = (search.get('fromDate') ?? '').trim() || fallback.fromDate;
  const toDate = (search.get('toDate') ?? '').trim() || fallback.toDate;
  const debitAccount = (search.get('debitAccount') ?? '').trim();
  const creditAccount = (search.get('creditAccount') ?? '').trim();
  return { fromDate, toDate, debitAccount, creditAccount };
}

function mapRowTag(raw: PeriodicAllocationJournalListingRow['rowTag'], isTotal?: boolean): RowTag {
  if (raw === 'Total' || isTotal) return 'Total';
  return 'Detail';
}

function normalizeItems(items: PeriodicAllocationJournalListingRow[]): PeriodicAllocationJournalListingRow[] {
  return items.map(r => {
    const rowTag = mapRowTag(r.rowTag, r.isTotal);
    const isTotal = rowTag === 'Total' || Boolean(r.isTotal);
    return {
      ...r,
      rowTag,
      isTotal,
      isBold: Boolean(r.isBold) || isTotal,
      allocationAmount: Number(r.allocationAmount ?? 0),
      amountPerPeriod: Number(r.amountPerPeriod ?? 0),
      allocatedAmount: Number(r.allocatedAmount ?? 0),
      remainingAmount: Number(r.remainingAmount ?? 0),
      periodCount: Number(r.periodCount ?? 0),
    };
  });
}

function rowClass(tag: RowTag): string | undefined {
  if (tag === 'Total') return styles.rowToneTotal;
  return styles.rowToneDetail;
}

const BangKeButToanPhanBoDinhKyPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const [searchParams] = useSearchParams();
  const monthRange = monthStartEnd();
  const drill = readDrillDefaults(searchParams, monthRange);

  const [fromDate, setFromDate] = useState(drill.fromDate);
  const [toDate, setToDate] = useState(drill.toDate);
  const [debitAccount, setDebitAccount] = useState(drill.debitAccount);
  const [creditAccount, setCreditAccount] = useState(drill.creditAccount);

  const [items, setItems] = useState<PeriodicAllocationJournalListingRow[]>([]);
  const [appliedFrom, setAppliedFrom] = useState('');
  const [appliedTo, setAppliedTo] = useState('');
  const [appliedDebit, setAppliedDebit] = useState('');
  const [appliedCredit, setAppliedCredit] = useState('');
  const [hasViewed, setHasViewed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [filterError, setFilterError] = useState('');
  const { showTableLoading } = useCatalogTableBusy(loading);

  const summary = useMemo(() => {
    if (!hasViewed) return null;
    const total = items.find(r => mapRowTag(r.rowTag, r.isTotal) === 'Total');
    if (!total) return null;
    return {
      allocationAmount: Number(total.allocationAmount ?? 0),
      allocatedAmount: Number(total.allocatedAmount ?? 0),
      remainingAmount: Number(total.remainingAmount ?? 0),
    };
  }, [hasViewed, items]);

  const detailCount = useMemo(
    () => items.filter(r => mapRowTag(r.rowTag, r.isTotal) === 'Detail').length,
    [items],
  );

  const handleView = useCallback(() => {
    setFilterError('');
    const company = sessionCompany();
    if (!company) {
      setFilterError('Không xác định đơn vị');
      dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
      return;
    }
    const from = fromDate.trim();
    const to = toDate.trim();
    if (!from || !to) {
      setFilterError('Chọn khoảng ngày');
      dispatchAppToast(dispatch, { message: 'Chọn khoảng ngày', type: 'error' });
      return;
    }
    if (to < from) {
      setFilterError('Đến ngày phải ≥ Từ ngày');
      dispatchAppToast(dispatch, { message: 'Đến ngày phải ≥ Từ ngày', type: 'error' });
      return;
    }

    const debit = debitAccount.trim();
    const credit = creditAccount.trim();

    setLoading(true);
    analyticsService
      .getPeriodicAllocationJournalListing({
        fromDate: from,
        toDate: to,
        debitAccount: debit,
        creditAccount: credit,
        pageSize: 0,
      })
      .then(report => {
        setItems(normalizeItems(report.items ?? []));
        setAppliedFrom(from);
        setAppliedTo(to);
        setAppliedDebit(debit);
        setAppliedCredit(credit);
        setHasViewed(true);
      })
      .catch(err => {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được bảng kê bút toán phân bổ định kỳ'),
          type: 'error',
        });
      })
      .finally(() => setLoading(false));
  }, [creditAccount, debitAccount, dispatch, fromDate, toDate]);

  const onEnterView = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleView();
      }
    },
    [handleView],
  );

  const handleRefresh = useCallback(() => {
    const range = monthStartEnd();
    setFromDate(range.fromDate);
    setToDate(range.toDate);
    setDebitAccount('');
    setCreditAccount('');
    setFilterError('');
  }, []);

  const handleExport = useCallback(() => {
    if (!hasViewed || loading || !appliedFrom || !appliedTo) return;
    const fileName = `bang-ke-but-toan-phan-bo-dinh-ky_${appliedFrom}_${appliedTo}.xlsx`;
    void exportExcel(
      '/accounting/periodic-allocation-journal-listing/export-excel',
      {
        fromDate: appliedFrom,
        toDate: appliedTo,
        debitAccount: appliedDebit,
        creditAccount: appliedCredit,
        pageSize: 0,
      },
      fileName,
    ).catch(() => {
      /* toast already in exportExcel */
    });
  }, [appliedCredit, appliedDebit, appliedFrom, appliedTo, hasViewed, loading]);

  const handlePrint = useCallback(() => {
    window.print();
  }, []);

  const exportDisabled = !hasViewed || loading || !appliedFrom;

  const toolbarActions = useMemo<LinListToolbarActionDef[]>(
    () => [
      {
        id: 'refresh',
        action: 'refresh',
        placement: 'left',
        label: 'Làm mới',
        variant: 'secondary',
        testId: `${TEST_ID}-toolbar-refresh-btn`,
        disabled: loading,
        onClick: handleRefresh,
      },
      {
        id: 'export-excel',
        action: 'exportExcel',
        placement: 'left',
        label: 'Xuất Excel',
        variant: 'secondary',
        testId: `${TEST_ID}-export-excel`,
        disabled: exportDisabled,
        onClick: handleExport,
      },
      {
        id: 'print',
        action: 'print',
        placement: 'left',
        label: 'In',
        variant: 'secondary',
        testId: `${TEST_ID}-export-print`,
        disabled: !hasViewed || loading,
        onClick: handlePrint,
      },
    ],
    [exportDisabled, handleExport, handlePrint, handleRefresh, hasViewed, loading],
  );

  const subtitle =
    hasViewed && appliedFrom && appliedTo
      ? `Từ: ${formatDate(appliedFrom)} đến ngày ${formatDate(appliedTo)}`
      : undefined;

  const listBody = showTableLoading ? null : (
    <div className={erp.tableWrapper}>
      {subtitle ? (
        <div data-testid={`${TEST_ID}-subtitle`} className={reportStyles.subtitle} style={{ marginBottom: '0.5rem' }}>
          {subtitle}
        </div>
      ) : null}
      <table className={reportStyles.table} data-testid={`${TEST_ID}-grid`}>
        <thead>
          <tr>
            <th>Ngày C.Từ</th>
            <th>TK Nợ</th>
            <th>Tên TK Nợ</th>
            <th>TK Có</th>
            <th>Tên TK Có</th>
            <th>Diễn giải</th>
            <th>Bắt đầu phân bổ</th>
            <th className={reportStyles.colRight}>Số kỳ</th>
            <th className={reportStyles.colRight}>Giá trị phân bổ</th>
            <th className={reportStyles.colRight}>Giá trị phân bổ kỳ</th>
            <th className={reportStyles.colRight}>Đã phân bổ</th>
            <th className={reportStyles.colRight}>Còn lại</th>
          </tr>
        </thead>
        <tbody>
          {!hasViewed
            ? null
            : items.map((row, index) => {
                const tag = mapRowTag(row.rowTag, row.isTotal);
                const isTotal = tag === 'Total';
                return (
                  <tr
                    key={`${tag}|${row.sttRec ?? 'T'}|${index}`}
                    className={rowClass(tag)}
                    data-testid={`${TEST_ID}-row-${index}`}
                    data-row-tag={tag}
                    data-is-total={isTotal ? '1' : '0'}
                    data-stt-rec={row.sttRec ?? ''}
                    data-drillable="0"
                  >
                    <td>{isTotal || !row.voucherDate ? '' : formatDate(row.voucherDate)}</td>
                    <td>{isTotal ? '' : (row.debitAccount ?? '')}</td>
                    <td>{isTotal ? '' : (row.debitAccountName ?? '')}</td>
                    <td>{isTotal ? '' : (row.creditAccount ?? '')}</td>
                    <td>{isTotal ? '' : (row.creditAccountName ?? '')}</td>
                    <td>{row.description ?? ''}</td>
                    <td>{isTotal || !row.allocationStartDate ? '' : formatDate(row.allocationStartDate)}</td>
                    <td className={reportStyles.colRight}>{isTotal ? '0' : String(row.periodCount ?? 0)}</td>
                    <td className={reportStyles.colRight}>{formatVnd(Number(row.allocationAmount ?? 0))}</td>
                    <td className={reportStyles.colRight}>{formatVnd(Number(row.amountPerPeriod ?? 0))}</td>
                    <td className={reportStyles.colRight}>{formatVnd(Number(row.allocatedAmount ?? 0))}</td>
                    <td className={reportStyles.colRight}>{formatVnd(Number(row.remainingAmount ?? 0))}</td>
                  </tr>
                );
              })}
        </tbody>
      </table>
      {hasViewed && detailCount === 0 ? (
        <div className={erp.empty} data-testid={`${TEST_ID}-empty`}>
          Không có dữ liệu
        </div>
      ) : null}
    </div>
  );

  const footer =
    hasViewed && summary ? (
      <div className={styles.summaryBar} data-testid={`${TEST_ID}-summary`}>
        <span>Gt_Pb: {formatVnd(summary.allocationAmount)}</span>
        <span>Đã PB: {formatVnd(summary.allocatedAmount)}</span>
        <span>Còn lại: {formatVnd(summary.remainingAmount)}</span>
      </div>
    ) : undefined;

  return (
    <div
      className={erp.voucherListRoot}
      data-catalog-list-page
      data-report-list-page
      data-testid={`${TEST_ID}-list`}
    >
      <LinPageLayout
        kind="report"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{ title: TITLE, titleIconClass: 'fas fa-list-alt' }}
        listTitle={TITLE}
        filterMaxWidthPx={1200}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        toolbarProps={{
          testIdPrefix: TEST_ID,
          profile: 'report',
          actions: toolbarActions,
        }}
        footer={footer}
        filters={(
          <>
            <div data-testid={`${TEST_ID}-field-fromDate`}>
              <Input
                type="date"
                label="Từ ngày"
                value={fromDate}
                onChange={e => setFromDate(e.target.value)}
                onKeyDown={onEnterView}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-toDate`}>
              <Input
                type="date"
                label="Đến ngày"
                value={toDate}
                onChange={e => setToDate(e.target.value)}
                onKeyDown={onEnterView}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-debitAccount`}>
              <Input
                label="TK Nợ"
                value={debitAccount}
                onChange={e => setDebitAccount(e.target.value)}
                onKeyDown={onEnterView}
                placeholder="Tất cả"
              />
            </div>
            <div data-testid={`${TEST_ID}-field-creditAccount`}>
              <Input
                label="TK Có"
                value={creditAccount}
                onChange={e => setCreditAccount(e.target.value)}
                onKeyDown={onEnterView}
                placeholder="Tất cả"
              />
            </div>
            <Button
              variant="primary"
              onClick={handleView}
              disabled={loading}
              data-testid={`${TEST_ID}-view-btn`}
            >
              Xem
            </Button>
            {filterError ? (
              <div className={styles.filterError} data-testid={`${TEST_ID}-filter-error`}>
                {filterError}
              </div>
            ) : null}
          </>
        )}
      >
        {listBody}
      </LinPageLayout>
    </div>
  );
};

export default BangKeButToanPhanBoDinhKyPage;
